package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Real RouterOS monitoring and report view; polls only on explicit refresh. */
public final class MonitoringActivity extends Activity {private TextView status,output;private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean report;@Override public void onCreate(Bundle b){super.onCreate(b);report="reports".equals(getIntent().getStringExtra("section"));LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(16,20,16,30);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);TextView t=new TextView(this);t.setText(report?"التقارير":"مراقبة الراوتر");t.setTextSize(24);t.setTextColor(Color.rgb(22,47,80));p.addView(t);status=txt("جاهز",14);p.addView(status);output=txt("اضغط تحديث لقراءة القياسات الحقيقية",15);p.addView(output);Button refresh=new Button(this);refresh.setText("تحديث القياسات");refresh.setOnClickListener(v->load());p.addView(refresh);load();}
 private void load(){status.setText("جاري القراءة...");worker.execute(()->{try{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);Map<String,String> m=first(r.execute("/system/resource/print","=.proplist=version,board-name,cpu-load,free-memory,total-memory,free-hdd-space,total-hdd-space,uptime"));int hot=r.execute("/ip/hotspot/active/print","=.proplist=.id").size();int ppp=r.execute("/ppp/active/print","=.proplist=.id").size();List<Map<String,String>> ifaces=r.execute("/interface/print","=.proplist=name,running,rx-byte,tx-byte");StringBuilder b=new StringBuilder();b.append("RouterOS: ").append(m.getOrDefault("version","--")).append("\nالجهاز: ").append(m.getOrDefault("board-name","--")).append("\nCPU: ").append(m.getOrDefault("cpu-load","--")).append("%\nRAM: ").append(m.getOrDefault("free-memory","--")).append(" / ").append(m.getOrDefault("total-memory","--")).append("\nالتخزين: ").append(m.getOrDefault("free-hdd-space","--")).append(" / ").append(m.getOrDefault("total-hdd-space","--")).append("\nUptime: ").append(m.getOrDefault("uptime","--")).append("\nHotspot نشط: ").append(hot).append("\nPPPoE نشط: ").append(ppp).append("\n\nالواجهات:\n");for(Map<String,String> x:ifaces)b.append(x.getOrDefault("name","--")).append(" | ").append(x.getOrDefault("running","--")).append(" RX ").append(x.getOrDefault("rx-byte","--")).append(" TX ").append(x.getOrDefault("tx-byte","--")).append('\n');ui(()->{status.setText("تم التحديث من الراوتر النشط");output.setText(b.toString());});}}catch(Exception e){ui(()->{status.setText("تعذر القراءة");output.setText(e.getMessage()==null?"خطأ غير معروف":e.getMessage());});}});}private Map<String,String> first(List<Map<String,String>> x){return x.isEmpty()?Collections.emptyMap():x.get(0);}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
